<template><main class="admin-content"><div class="mb-6"><p class="text-xs font-black uppercase tracking-wider text-blue-600">SuperAdmin</p><h1 class="text-3xl font-black">Accounting</h1><p class="text-slate-500">Double-entry accounting foundation for Kialla Computers.</p></div><div v-if="err" class="mb-4 rounded-lg bg-red-50 p-3 text-red-700">{{err}}</div><div class="grid gap-4 md:grid-cols-4"><div class="admin-panel p-5"><small>Accounts</small><div class="text-3xl font-black">{{accounts.length}}</div></div><div class="admin-panel p-5"><small>Posted Journals</small><div class="text-3xl font-black">{{journals.length}}</div></div><div class="admin-panel p-5"><small>Total Debits</small><div class="text-2xl font-black">{{money(totalDebits)}}</div></div><div class="admin-panel p-5"><small>Total Credits</small><div class="text-2xl font-black">{{money(totalCredits)}}</div></div></div><div class="mt-5 grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><section class="admin-panel p-5"><div class="flex justify-between"><div><h2 class="text-xl font-black">Trial Balance</h2><p class="text-sm text-slate-500">Posted journal activity by account.</p></div><button class="btn-secondary" @click="load">Refresh</button></div><div class="mt-4 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Code</th><th>Account</th><th>Type</th><th class="text-right">Debit</th><th class="text-right">Credit</th></tr></thead><tbody><tr v-for="a in trial" :key="a.id" class="border-b"><td class="p-2 font-mono">{{a.code}}</td><td>{{a.name}}</td><td class="capitalize">{{a.account_type}}</td><td class="text-right">{{money(a.debit)}}</td><td class="text-right">{{money(a.credit)}}</td></tr></tbody></table></div></section><section class="admin-panel p-5"><h2 class="text-xl font-black">Accounting Tools</h2><div class="mt-4 grid gap-3"><NuxtLink class="tool" to="/admin/accounting/accounts"><b>Chart of Accounts</b><span>Create and review ledger accounts.</span></NuxtLink><NuxtLink class="tool" to="/admin/accounting/journals"><b>General Journal</b><span>Post balanced manual journals.</span></NuxtLink><NuxtLink class="tool" to="/admin/accounting/invoices"><b>Sales &amp; Invoices</b><span>Paid orders, GST and automatic sales journals.</span></NuxtLink></div><div class="mt-6 rounded-xl bg-amber-50 p-4 text-sm text-amber-900"><b>Stage 1 foundation</b><p class="mt-1">Sales, purchases, bank reconciliation, inventory accounting, GST/BAS and financial reports will connect to this ledger in the next stages.</p></div></section></div></main></template><script setup lang="ts">definePageMeta({layout:"admin",middleware:["admin"]});const{adminFetch,isSuperAdmin}=useAdminFetch();const accounts=ref<any[]>([]),journals=ref<any[]>([]),trial=ref<any[]>([]),err=ref("");const money=(v:any)=>new Intl.NumberFormat("en-AU",{style:"currency",currency:"AUD"}).format(Number(v||0));const totalDebits=computed(()=>trial.value.reduce((s,a)=>s+Number(a.debit||0),0));const totalCredits=computed(()=>trial.value.reduce((s,a)=>s+Number(a.credit||0),0));async function load(){err.value="";try{if(!isSuperAdmin.value)return navigateTo("/admin");[accounts.value,journals.value,trial.value]=await Promise.all([adminFetch("/api/admin/accounting/accounts"),adminFetch("/api/admin/accounting/journals"),adminFetch("/api/admin/accounting/trial-balance")])}catch(e:any){err.value=e?.data?.statusMessage||e.message}}onMounted(load)</script><style scoped>.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold}.tool{@apply flex flex-col rounded-xl border p-4 hover:border-blue-300 hover:bg-blue-50}.tool span{@apply mt-1 text-sm text-slate-500}</style>